// LearnsetTable.movesAt(speciesKey, level) -> the moves the species would know at that level (latest 4 level-up moves)
Object.defineProperty(LearnsetTable, 'movesAt', { enumerable: false, value(key, level) {
  const e = this[key]; if (!e || !e.levelUp) return [];
  const out = []; for (const [lv, mv] of e.levelUp) { if (lv <= level && !out.includes(mv)) out.push(mv); }
  return out.slice(-4);
} });
window.LearnsetTable = LearnsetTable;
